  col += SP_WHITE * (turnBand(dr, -0.05, -0.043, px) + turnBand(dr, 0.043, 0.05, px)) * 0.2 * breath;
  // never the angle at the middle, where atan(0, 0) is no number (the resonance's AUDIT)
