    col += SP_BEACON * bowl * 0.55 + (SP_WHITE * 0.9 + SP_BEACON * 0.4) * heart + SP_WHITE * glint * 0.9;
    col += SP_BEACON * exp(-dot(d, d) / 0.012) * 0.25 * lit;   // its light on the stone about it
